INSERT INTO releases (version, title, notes, released_at) VALUES ('v0.5.0', 'Deal Pipeline Overhaul', ARRAY['Starter pool generator: 200 sims (Klondike), 50 sims (FreeCell), up to 8000 candidates, no time limit', 'Target: 75 Easy + 50 Medium per game mode (300 total starter deals)', 'All verified solvable deals banked — Easy/Medium as starter tier, Hard/Expert as fresh tier', 'Active working set of 25 deals per game mode for focused empirical DDS calibration', 'Deals graduate from working set at 30 pool_attempts, backfilled from full pool', 'Working set priority: starter deals first, then closest to graduation, then oldest', 'New deal_working_set table tracks active set membership server-side', 'refill-deal-queue edge function manages working set lifecycle automatically'], '2025-03-25T12:00:00Z');